tool_and_message_events.command:
/bin/bash -lc "python - <<'PY'
import json,struct,pathlib
p=pathlib.Path('distribution/shift.asar'); data=p.read_bytes(); a,b,c,d=struct.unpack_from('<IIII',data); print(len(data),a,b,c,d); h=json.loads(data[16:16+d]); print(h)
for name,ent in h['files'].items():
 if 'offset' in ent:
  o=8+b+int(ent['offset']); raw=data[o:o+ent['size']]; f=p.parent/name; print(name, 'matches companion:', f.is_file() and raw==f.read_bytes());
  if f.is_file() and raw"'!=f.read_bytes():
   import difflib
   print('"''.join(difflib.unified_diff(f.read_text().splitlines(True),raw.decode().splitlines(True))))
PY"

